"""Pure decision policy: database facts + configured identity -> PROCEED or a refusal.

``decide`` has no I/O. It raises ``GuardRefused`` for every condition that is not an
explicitly allowed mode, so the default is refusal.

Identity is checked on independently provisioned factors, never on names alone:

* PostgreSQL's ``system_identifier`` (generated by initdb, recorded in the marker);
* the operator-provisioned ``instance_id`` (configuration and marker must agree);
* ``cluster_name``, database name and the connected role (``current_user`` and ``session_user``);
* the marker's recorded environment, database and cluster.

A restored dump keeps its marker but lands in a cluster with a different system
identifier, so it is refused. An unknown, populated database has no marker and is refused.
"""

from dataclasses import dataclass

from app.guard.errors import GuardRefused
from app.guard.facts import Facts, Marker, provisioning_verified
from app.guard.lineage import GRANTING_REVISION, Lineage

MIN_SERVER_VERSION = 170000
DATA_CHANGING = frozenset({"0004", "0019", "0025", "0027", "0029"})
OPERATIONS = ("upgrade", "downgrade", "stamp")


@dataclass(frozen=True)
class Decision:
    mode: str  # PROCEED-RUNTIME, INIT, UPGRADE, NOOP, DOWNGRADE
    from_revision: str | None = None
    target: str | None = None
    steps: tuple[str, ...] = ()

    @property
    def data_changing_steps(self) -> tuple[str, ...]:
        return tuple(s for s in self.steps if s in DATA_CHANGING)

    @property
    def changes_schema(self) -> bool:
        return self.mode in ("INIT", "UPGRADE", "DOWNGRADE")


def _identity(facts: Facts, identity, required_user: str) -> None:
    if facts.server_version_num < MIN_SERVER_VERSION:
        raise GuardRefused("NXG-I06", env=identity.environment)
    if facts.database != identity.database.name:
        raise GuardRefused("NXG-I02", env=identity.environment)
    if facts.cluster_name != identity.expected_cluster:
        raise GuardRefused("NXG-I03", env=identity.environment)
    # First-boot provisioning must have completed: an initialized data directory
    # whose role/privilege setup was interrupted is refused for runtime and migration.
    # Established by the stored database-level setting, never by the session value alone.
    if not provisioning_verified(facts):
        raise GuardRefused("NXG-I10", env=identity.environment)
    # session_user too: a role switched with SET ROLE does not count.
    if facts.current_user != required_user or facts.session_user != required_user:
        raise GuardRefused("NXG-I04", env=identity.environment)
    if facts.superuser or facts.createrole or facts.bypassrls or facts.replication:
        raise GuardRefused("NXG-I05", env=identity.environment)
    ci_owner = identity.role == "migrator" and identity.environment in ("ci", "test")
    if facts.createdb and not ci_owner:
        raise GuardRefused("NXG-I05", env=identity.environment)
    if identity.role == "runtime" and (
        facts.can_create_in_database
        or facts.can_create_in_schema
        or facts.member_of_owner
        or facts.guard_tables_writable  # alembic_version, marker or ledger
    ):
        raise GuardRefused("NXG-I05", env=identity.environment)
    if not facts.system_identifier:
        raise GuardRefused("NXG-I07", env=identity.environment)


def _marker(facts: Facts, identity) -> Marker:
    if len(facts.markers) != 1:
        raise GuardRefused("NXG-L05", env=identity.environment)
    marker = facts.markers[0]
    if marker.lineage != "nextup":
        raise GuardRefused("NXG-L05", env=identity.environment)
    if marker.environment != identity.environment:
        raise GuardRefused("NXG-M02", env=identity.environment)
    if (
        marker.database_name != facts.database
        or marker.cluster_name != facts.cluster_name
        or marker.system_identifier != facts.system_identifier
    ):
        raise GuardRefused("NXG-M03", env=identity.environment)
    configured = None if identity.instance_id is None else str(identity.instance_id)
    if marker.instance_id != configured:
        raise GuardRefused("NXG-M04", env=identity.environment)
    return marker


def _revision(facts: Facts, identity, lineage: Lineage) -> str:
    if not facts.alembic_present or not facts.alembic_versions:
        raise GuardRefused("NXG-L05", env=identity.environment)
    if len(facts.alembic_versions) != 1:
        raise GuardRefused("NXG-L02", env=identity.environment)
    current = facts.alembic_versions[0]
    if current not in lineage:
        raise GuardRefused("NXG-L01", env=identity.environment)
    return current


def _grants(facts: Facts, identity, settings, *, crossing_grant: bool) -> None:
    classifier = bool(getattr(settings, "external_classifier_enabled", False))
    if facts.classifier_role_exists and not classifier and crossing_grant:
        raise GuardRefused("NXG-R01", env=identity.environment)
    if facts.foreign_grantees and not classifier:
        raise GuardRefused("NXG-R02", env=identity.environment)


def _is_empty(facts: Facts) -> bool:
    return not facts.marker_present and not facts.alembic_present and facts.application_tables == 0


def decide_runtime(facts: Facts, identity, lineage: Lineage, settings=None) -> Decision:
    """Startup check for api, worker and scheduler (read-only)."""
    if identity.role != "runtime":
        raise GuardRefused("NXG-I04", env=identity.environment)
    _identity(facts, identity, identity.expected_user)
    if not facts.marker_present:
        raise GuardRefused("NXG-M05" if _is_empty(facts) else "NXG-M01", env=identity.environment)
    _marker(facts, identity)
    current = _revision(facts, identity, lineage)
    if current != lineage.head:
        raise GuardRefused("NXG-L03", env=identity.environment)
    # At or beyond 0029 the grant may already have happened: a classifier role is refused.
    _grants(
        facts,
        identity,
        settings,
        crossing_grant=lineage.index(current) >= lineage.index(GRANTING_REVISION),
    )
    return Decision("PROCEED-RUNTIME", current, current)


def decide_migration(
    facts: Facts,
    identity,
    lineage: Lineage,
    *,
    operation: str = "upgrade",
    target: str | None = None,
    settings=None,
) -> Decision:
    """Plan a schema change. Never executes; ``plan`` turns the result into an authorization."""
    env = identity.environment
    if identity.role != "migrator":
        raise GuardRefused("NXG-I04", env=env)
    if operation not in OPERATIONS or operation == "stamp":
        raise GuardRefused("NXG-A06", env=env)
    target = lineage.head if target is None else target
    if target not in lineage:
        raise GuardRefused("NXG-L01", env=env)
    _identity(facts, identity, identity.expected_user)

    if _is_empty(facts):
        if operation != "upgrade":
            raise GuardRefused("NXG-A06", env=env)
        if not facts.pg_trgm:
            raise GuardRefused("NXG-I08", env=env)
        _grants(
            facts,
            identity,
            settings,
            crossing_grant=lineage.crosses(None, target, GRANTING_REVISION),
        )
        steps = lineage.order[: lineage.index(target) + 1]
        return Decision("INIT", None, target, steps)

    if not facts.marker_present:
        raise GuardRefused("NXG-M01", env=env)
    _marker(facts, identity)
    current = _revision(facts, identity, lineage)
    here, there = lineage.index(current), lineage.index(target)

    if operation == "upgrade":
        if there < here:
            raise GuardRefused("NXG-A06", env=env)
        _grants(
            facts,
            identity,
            settings,
            crossing_grant=lineage.crosses(current, target, GRANTING_REVISION),
        )
        if there == here:
            return Decision("NOOP", current, target)
        return Decision("UPGRADE", current, target, lineage.order[here + 1 : there + 1])

    # downgrade: disposable environments only
    if env not in ("ci", "test") or there >= here:
        raise GuardRefused("NXG-A06", env=env)
    _grants(facts, identity, settings, crossing_grant=False)
    return Decision(
        "DOWNGRADE", current, target, tuple(reversed(lineage.order[there + 1 : here + 1]))
    )
